import pyomo.environ as pyo

DATA = {
    "num_clients": 5,
    "num_operations": 2,
    "duration": 1,
    "min_gap": 1,
    "big_m": 100000,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.clients = pyo.RangeSet(0, d["num_clients"] - 1)
    model.operations = pyo.RangeSet(0, d["num_operations"] - 1)

    # All (client, operation) pairs
    op_pairs = [
        (i, o)
        for i in range(d["num_clients"])
        for o in range(d["num_operations"])
    ]

    # Ordered pairs (a, b) with a < b lexicographically, for disjunctive binaries
    ordered_pairs = [
        (a[0], a[1], b[0], b[1])
        for idx_a, a in enumerate(op_pairs)
        for b in op_pairs[idx_a + 1:]
    ]

    model.op_pairs = pyo.Set(initialize=op_pairs, dimen=2)
    model.ordered_pairs = pyo.Set(initialize=ordered_pairs, dimen=4)

    # Variables
    model.start = pyo.Var(
        model.clients, model.operations, within=pyo.NonNegativeReals
    )
    model.makespan = pyo.Var(within=pyo.NonNegativeReals)
    model.precedes = pyo.Var(model.ordered_pairs, within=pyo.Binary)

    # Objective: minimize makespan
    def obj_rule(m):
        return m.makespan

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: sequence within each client (op 1 after op 0 + gap)
    def sequence_rule(m, i):
        return (
            m.start[i, 1]
            >= m.start[i, 0] + d["duration"] + d["min_gap"]
        )

    model.sequence = pyo.Constraint(model.clients, rule=sequence_rule)

    # Constraint: makespan dominates every operation's completion time
    def makespan_rule(m, i, o):
        return m.makespan >= m.start[i, o] + d["duration"]

    model.makespan_bound = pyo.Constraint(
        model.clients, model.operations, rule=makespan_rule
    )

    # Constraint: non-overlap on the shared machine (disjunctive, big-M)
    def nonoverlap_rule(m, i, o, j, p):
        return (
            m.start[j, p]
            >= m.start[i, o] + d["duration"]
            - d["big_m"] * (1 - m.precedes[i, o, j, p])
        )

    model.nonoverlap = pyo.Constraint(
        model.ordered_pairs, rule=nonoverlap_rule
    )

    def nonoverlap_reverse_rule(m, i, o, j, p):
        return (
            m.start[i, o]
            >= m.start[j, p] + d["duration"]
            - d["big_m"] * m.precedes[i, o, j, p]
        )

    model.nonoverlap_reverse = pyo.Constraint(
        model.ordered_pairs, rule=nonoverlap_reverse_rule
    )

    return model


